CREATE Proc [dbo].[InsertOrderDetailKOT] @order_key as nvarchar(50), @date as datetime,@z_number  nvarchar(50),@category_name nvarchar(50),@item_name nvarchar(50),@qty as decimal,@price as float,@tiltid as int,@CounterId as int,@Discount as decimal,@PricebeforeDiscount as decimal(18,2),@ItemId as int,@Comments as nvarchar(50),@Is_IsComments as bit,@actual_tax as float as BEGIN TRY BEGIN TRANSACTION  Declare @Count as int;set @Count=0;Declare @tax_ as decimal;set @tax_=0;select @tax_ = (@PricebeforeDiscount - @Discount)  * @actual_tax Insert into Order_detail (order_key,date,z_number,category_name,item_name,qty,price,tiltid,CounterId,Discount,PricebeforeDiscount,ItemId,Comments,Is_IsComments,tax) values(@order_key,@date,@z_number,@category_name,@item_name,@qty,@price,@tiltid,@CounterId,@Discount,@PricebeforeDiscount,@ItemId,@Comments,@Is_IsComments,@tax_)  SELECT  @Count = SCOPE_IDENTITY();IF @Count > 0 Update Order_detail set parent_Id = @Count where id = @Count Insert into OrderKot(orderkey,ItemId,Qty,KotStatus,Comments,Tiltid,ItemComment,LessReason,OrderDetailId,order_type)values(@order_key,@ItemId,@qty,0,'',@tiltid,@Comments,'',@Count,'pos') SELECT  @Count COMMIT END TRY BEGIN CATCH IF @@TRANCOUNT > 0 ROLLBACK  exec uspGetErrorInfo END CATCH